sketch.css:
.lu{display:flex;flex-direction:column;height:100%;padding:12px 14px;background:var(--surface);color:var(--text);font:12px Segoe UI,system-ui,sans-serif;box-sizing:border-box}
.head{display:flex;align-items:baseline;gap:10px;margin-bottom:8px}
.title{font-weight:700;font-size:14px}
.tot{flex:1;color:var(--muted)}.tot b{color:var(--text)}
.flag{font-weight:700;font-size:11px;padding:1px 9px;border-radius:10px;background:var(--chip)}
.flag.bad{color:var(--negative)}.flag.ok{color:var(--positive)}
.rows{flex:1;overflow:auto;display:flex;flex-direction:column;gap:1px}
.row{display:flex;align-items:center;gap:8px;padding:4px 6px;border-radius:6px;border:1px solid transparent;cursor:pointer}
.row:hover{background:var(--hover)}.row.selected{background:var(--hover);border-color:var(--accent)}
.who{width:150px;display:flex;align-items:center;gap:6px;min-width:0}
.name{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rating{font-size:10px;font-weight:700;padding:0 6px;border-radius:8px;border:1px solid var(--border);color:var(--muted)}
.track{flex:1;position:relative;height:12px;background:var(--border);border-radius:5px}
.fill{position:absolute;left:0;top:0;bottom:0;border-radius:5px}
.mark{position:absolute;top:-2px;bottom:-2px;width:2px;background:var(--text);opacity:.55}
.pct{width:44px;text-align:right;font-weight:700}
.chip{width:56px;text-align:center;font-size:11px;font-weight:700;padding:1px 0;border-radius:10px;background:var(--chip)}

sketch.js:
function render(root, props, fire) {
  var rows = (props.rows || []).map(function (r) { var l = +r.limit || 0, e = +r.exposure || 0; return { name: r.name, e: e, l: l, rating: r.rating || '', p: l > 0 ? e / l : (e > 0 ? 9.99 : 0) }; });
  rows.sort(function (a, b) { return b.p - a.p; });
  var warn = props.warnAt > 0 ? props.warnAt : 0.8, unit = props.unit || '';
  var te = 0, tl = 0, br = 0;
  rows.forEach(function (r) { te += r.e; tl += r.l; if (r.p > 1) br++; });
  root.querySelector('.title').textContent = props.title || '';
  root.querySelector('.tot').innerHTML = '<b>' + te + '</b> / ' + tl + ' ' + unit;
  var f = root.querySelector('.flag'); f.textContent = br ? br + ' in breach' : 'No breaches'; f.className = 'flag ' + (br ? 'bad' : 'ok');
  var scale = Math.max(1, rows.reduce(function (m, r) { return Math.max(m, r.p); }, 0));
  var box = root.querySelector('.rows'); box.innerHTML = '';
  rows.forEach(function (r) {
    var st = r.p > 1 ? ['Breach', 'negative'] : r.p >= warn ? ['Watch', 'warning'] : ['OK', 'positive'];
    var d = document.createElement('div'); d.className = 'row' + (r.name === props.selected ? ' selected' : '');
    d.title = r.name + ': ' + r.e + ' of ' + r.l + ' ' + unit + ', headroom ' + (r.l - r.e) + ' ' + unit;
    d.innerHTML = '<div class="who"><span class="name"></span><span class="rating"></span></div><div class="track"><div class="fill" style="width:' + (Math.min(r.p, scale) / scale * 100) + '%;background:var(--' + st[1] + ')"></div><div class="mark" style="left:' + (warn / scale * 100) + '%"></div></div><div class="pct">' + Math.round(r.p * 100) + '%</div><div class="chip" style="color:var(--' + st[1] + ')">' + st[0] + '</div>';
    d.querySelector('.name').textContent = r.name; d.querySelector('.rating').textContent = r.rating;
    if (!r.rating) d.querySelector('.rating').style.display = 'none';
    d.onclick = function () { fire('rowSelected', { name: r.name, selected: r.name }); };
    box.appendChild(d);
  });
}
